INSERT INTO "produto" ("id", "slug", "nome", "descricao", "preco", "codigo_moeda", "quantidade_stock", "criado_em", "actualizado_em", "activo", "categoria_id", "codigo", "especificacoes", "garantia", "limiar_stock_baixo", "marca") VALUES ('seed-easyshop-produto-001', 'seed-capacetes-de-seguranca-1', 'Capacete MSA V-Gard 500 laranja', 'Capacete de segurança industrial com casco em ABS e ventilação lateral regulável, ideal para obras de construção civil, armazéns e indústria. A suspensão Fas-Trac III de 4 pontos com ajuste por roda distribui o peso e reduz a fadiga em turnos longos. Possui ranhuras laterais para abafadores e viseiras, e calha para escoamento da água da chuva. Certificado segundo a norma EN 397.', '1850.00', 'MZN', '30', '2026-05-20T01:12:00.000Z', '2026-11-05T10:26:28.141Z', TRUE, '13', 'SEED-ES-0001', '{"Cor":"Laranja","Peso":"Aprox. 380 g","Marca":"MSA","Modelo":"V-Gard 500","Normas":"EN 397, EN 50365 (440 V CA)","material":"ABS","categoria":"Capacetes de segurança","Suspensão":"Fas-Trac III, 4 pontos, ajuste por roda","Acessórios":"Ranhuras de 30 mm para abafadores e viseiras","Ventilação":"Sim, regulável","Material do casco":"ABS","Tamanho da cabeça":"52–64 cm","Vida útil recomendada":"5 anos a partir da data de fabrico"}'::jsonb, 'Garantia do fabricante contra defeitos de fabrico.', '5', 'MSA');
INSERT INTO "produto" ("id", "slug", "nome", "descricao", "preco", "codigo_moeda", "quantidade_stock", "criado_em", "actualizado_em", "activo", "categoria_id", "codigo", "especificacoes", "garantia", "limiar_stock_baixo", "marca") VALUES ('seed-easyshop-produto-002', 'seed-capacetes-de-seguranca-2', 'Capacete 3M Peltor G3000 com abafadores', 'Capacete 3M G3000 com abafadores Peltor acoplados, para quem trabalha em ambientes ruidosos com risco de queda de objectos, como estaleiros, pedreiras e serralharias. O indicador UV muda de cor quando o casco precisa de ser substituído por envelhecimento solar, algo importante no clima de Moçambique. Os abafadores rebatem-se para cima quando não estão a ser usados.', '2450.00', 'MZN', '0', '2026-05-20T02:24:00.000Z', '2026-11-05T10:26:28.154Z', TRUE, '13', 'SEED-ES-0002', '{"Peso":"Aprox. 650 g (com abafadores)","Marca":"3M","Modelo":"G3000 com abafadores Peltor","Normas":"EN 397, EN 352-3","material":"ABS","categoria":"Capacetes de segurança","Suspensão":"6 pontos, ajuste por roda","Indicador UV":"Sim (Uvicator)","Ventilação":"Sim","Material do casco":"ABS com estabilização UV","Tamanho da cabeça":"54–62 cm","Atenuação dos abafadores":"SNR 27 dB"}'::jsonb, 'Garantia do fabricante contra defeitos de fabrico.', '5', '3M');
INSERT INTO "produto" ("id", "slug", "nome", "descricao", "preco", "codigo_moeda", "quantidade_stock", "criado_em", "actualizado_em", "activo", "categoria_id", "codigo", "especificacoes", "garantia", "limiar_stock_baixo", "marca") VALUES ('seed-easyshop-produto-003', 'seed-capacetes-de-seguranca-3', 'Capacete Delta Plus Diamond V amarelo', 'Capacete leve e económico, muito usado em equipas de obra e manutenção. O arnês têxtil de 8 pontos e a banda anti-suor tornam-no confortável em dias quentes. Aceita viseira e abafadores através das ranhuras laterais. Adequado para trabalhos gerais de construção civil.', '1250.00', 'MZN', '3', '2026-05-20T03:36:00.000Z', '2026-11-05T10:26:28.157Z', TRUE, '13', 'SEED-ES-0003', '{"Cor":"Amarelo","Peso":"Aprox. 350 g","Marca":"Delta Plus","Arnês":"Têxtil, 8 pontos","Modelo":"Diamond V","Normas":"EN 397","material":"ABS","categoria":"Capacetes de segurança","Ventilação":"Sim","Material do casco":"ABS","Tamanho da cabeça":"53–63 cm","Banda de transpiração":"Sim, substituível"}'::jsonb, 'Garantia do fabricante contra defeitos de fabrico.', '5', 'Delta Plus');
INSERT INTO "produto" ("id", "slug", "nome", "descricao", "preco", "codigo_moeda", "quantidade_stock", "criado_em", "actualizado_em", "activo", "categoria_id", "codigo", "especificacoes", "garantia", "limiar_stock_baixo", "marca") VALUES ('seed-easyshop-produto-004', 'seed-capacetes-de-seguranca-4', 'Capacete Portwest Endurance PS55 (várias cores)', 'Capacete Portwest Endurance disponível em 10 cores, permitindo identificar funções em obra (encarregado, electricista, visitante, segurança). Casco em HDPE com aba curta e suspensão com roda dentada. É uma solução prática para empresas que querem padronizar o EPI da equipa por cores.', '1550.00', 'MZN', '39', '2026-05-20T04:48:00.000Z', '2026-11-05T10:26:28.160Z', TRUE, '13', 'SEED-ES-0004', '{"Peso":"Aprox. 370 g","Cores":"Branco, amarelo, laranja, vermelho, azul, verde, preto e outras","Marca":"Portwest","Modelo":"Endurance PS55","Normas":"EN 397","material":"HDPE","categoria":"Capacetes de segurança","Suspensão":"6 pontos, ajuste por roda dentada","Ventilação":"Sim","Material do casco":"HDPE","Tamanho da cabeça":"53–63 cm"}'::jsonb, 'Garantia do fabricante contra defeitos de fabrico.', '5', 'Portwest');
INSERT INTO "produto" ("id", "slug", "nome", "descricao", "preco", "codigo_moeda", "quantidade_stock", "criado_em", "actualizado_em", "activo", "categoria_id", "codigo", "especificacoes", "garantia", "limiar_stock_baixo", "marca") VALUES ('seed-easyshop-produto-005', 'seed-capacetes-de-seguranca-5', 'Capacete Honeywell North Zone N10 branco', 'Capacete de perfil baixo com suspensão de 4 pontos e ventilação lateral, pensado para técnicos, engenheiros e supervisores. A cor branca reflecte o calor e identifica funções de chefia em obra. Compatível com acessórios Honeywell (viseira e abafadores).', '1950.00', 'MZN', '40', '2026-05-20T06:00:00.000Z', '2026-11-05T10:26:28.162Z', TRUE, '13', 'SEED-ES-0005', '{"Cor":"Branco","Peso":"Aprox. 360 g","Marca":"Honeywell","Modelo":"North Zone N10","Normas":"EN 397","material":"ABS","categoria":"Capacetes de segurança","Suspensão":"4 pontos, ajuste por roda","Ventilação":"Lateral","Material do casco":"ABS","Tamanho da cabeça":"53–63 cm"}'::jsonb, 'Garantia do fabricante contra defeitos de fabrico.', '5', 'Honeywell');
