INSERT INTO "produto" ("id", "slug", "nome", "descricao", "preco", "codigo_moeda", "quantidade_stock", "criado_em", "actualizado_em", "activo", "categoria_id", "codigo", "especificacoes", "garantia", "limiar_stock_baixo", "marca") VALUES ('seed-easyshop-produto-051', 'seed-equipamento-contra-incendios-51', 'Extintor ABC 6kg pó químico', 'Extintor portátil de pó químico ABC para incêndios de sólidos, líquidos inflamáveis e gases, e eficaz em equipamento eléctrico até 1000 V. É o extintor mais versátil para escritórios, lojas, armazéns, viaturas pesadas e residências. Fornecido com suporte de parede e manómetro de pressão.', '3500.00', 'MZN', '30', '2026-05-22T13:12:00.000Z', '2026-11-05T10:26:28.275Z', TRUE, '21', 'SEED-ES-0051', '{"Marca":"Vonder","Normas":"EN 3","Alcance":"4–6 m","material":"Aço","categoria":"Equipamento contra incêndios","Capacidade":"6 kg","Peso total":"Aprox. 9,5 kg","Agente extintor":"Pó químico ABC (fosfato monoamónico)","Classes de fogo":"A, B, C","Pressurização":"Permanente (azoto), com manómetro","Tempo de descarga":"Aprox. 15 s","Conteúdo da embalagem":"Extintor e suporte de parede"}'::jsonb, 'Garantia do fabricante contra defeitos de fabrico.', '5', 'Vonder');
